	@Test
	void rightCursorPublishedAfterCancellationReceivesRequestBeforeClose() throws Exception {
		CountDownLatch opening = new CountDownLatch(1);
		CountDownLatch releaseOpening = new CountDownLatch(1);
		List<String> events = new ArrayList<>();
		class RightCursor implements CloseableIteration<BindingSet>, CooperativeCancellation {
			@Override
			public boolean hasNext() {
				throw new AssertionError("late cancelled cursor must not be advanced");
			}

			@Override
			public BindingSet next() {
				throw new AssertionError("late cancelled cursor must not be read");
			}

			@Override
			public boolean requestCancellation() {
				events.add("cancel");
				return true;
			}

			@Override
			public void close() {
				events.add("close");
			}
		}
		QueryEvaluationStep left = input -> rows(with(input, "leftOnly", LEFT));
		QueryEvaluationStep right = input -> {
			opening.countDown();
			try {
				if (!releaseOpening.await(10, TimeUnit.SECONDS)) {
					throw new AssertionError("the test did not release the right open");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new QueryEvaluationException(e);
			}
			return new RightCursor();
		};
		try (var executor = Executors.newSingleThreadExecutor();
				ScopedCorrelatedJoinIterator iteration = join(left, right, row("entry", ENTRY), true)) {
			var result = executor.submit(iteration::hasNext);
			try {
				assertThat(opening.await(10, TimeUnit.SECONDS)).isTrue();
				assertThat(iteration.requestCancellation()).isTrue();
			} finally {
				releaseOpening.countDown();
			}
			assertThatThrownBy(() -> result.get(10, TimeUnit.SECONDS))
					.hasCauseInstanceOf(QueryInterruptedException.class);
			assertThat(events).containsExactly("cancel", "close");
		}
	}

