	@Test
	void nestedOwnerRestorationKeepsAncestorProbeAndPopsOwnedFrame() {
		BindingFrameBindings.Scope ancestorOwner = new BindingFrameBindings.Scope();
		BindingFrameBindings.Scope owner = new BindingFrameBindings.Scope();
		BindingSet entry = BindingFrameBindings.push(ancestorOwner, row("entry", ENTRY), row("ancestor", ANCESTOR),
				CONTEXT);
		QueryEvaluationStep left = input -> rows(with(input, "leftOnly", LEFT));
		QueryEvaluationStep right = logical -> {
			assertThat(logical.getValue("leftOnly")).isNull();
			assertThat(BindingFrameBindings.probeValue(logical, "leftOnly")).isEqualTo(LEFT);
			assertThat(BindingFrameBindings.probeValue(logical, "ancestor")).isEqualTo(ANCESTOR);
			return rows(with(logical, "rightOnly", RIGHT));
		};

		List<BindingSet> results = collect(new ScopedCorrelatedJoinIterator(left, right, null, entry, CONTEXT, owner,
				true));

		assertThat(results).hasSize(1);
		BindingSet result = results.get(0);
		assertThat(result).isEqualTo(row("entry", ENTRY, "leftOnly", LEFT, "rightOnly", RIGHT));
		assertThat(BindingFrameBindings.probeValue(result, "ancestor")).isEqualTo(ANCESTOR);
		BindingSet restored = BindingFrameBindings.pop(ancestorOwner, result, CONTEXT);
		assertThat(BindingFrameBindings.hasFrame(restored)).isFalse();
		assertThat(BindingFrameBindings.probeValue(restored, "ancestor")).isNull();
	}

