	private static ScopedCorrelatedJoinIterator join(QueryEvaluationStep left, QueryEvaluationStep right,
			BindingSet entry, boolean optional) {
		return new ScopedCorrelatedJoinIterator(left, right, null, entry, CONTEXT,
				new BindingFrameBindings.Scope(), optional);
	}

	private static List<BindingSet> collect(CloseableIteration<BindingSet> iteration) {
		List<BindingSet> result = new ArrayList<>();
		try (iteration) {
			while (iteration.hasNext()) {
				result.add(iteration.next());
			}
		}
		return result;
	}

	private static CloseableIteration<BindingSet> rows(BindingSet... rows) {
		return new CloseableIteratorIteration<>(Arrays.asList(rows).iterator());
	}

	private static CloseableIteration<BindingSet> trackingRows(AtomicInteger closes, BindingSet... rows) {
		return new CloseableIteratorIteration<>(Arrays.asList(rows).iterator()) {
			@Override
			protected void handleClose() {
				closes.incrementAndGet();
			}
		};
	}

	private static QueryBindingSet row(Object... nameValues) {
		QueryBindingSet result = new QueryBindingSet();
		for (int i = 0; i < nameValues.length; i += 2) {
			result.addBinding((String) nameValues[i], (Value) nameValues[i + 1]);
		}
		return result;
	}

	private static QueryBindingSet with(BindingSet source, String name, Value value) {
		QueryBindingSet result = new QueryBindingSet(source);
		result.setBinding(name, value);
		return result;
	}

	private static Value literal(String label) {
		return SimpleValueFactory.getInstance().createLiteral(label);
	}
